const OPERATIONS = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b,
  divide: (a, b) => a / b,
};

export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers.',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number', description: 'The first operand.' },
          b: { type: 'number', description: 'The second operand.' },
          operation: {
            type: 'string',
            enum: ['add', 'subtract', 'multiply', 'divide'],
            description: 'The arithmetic operation to perform.',
          },
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const allowed = new Set(['a', 'b', 'operation']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  const { a, b, operation } = args;
  if (a === undefined) throw new Error('Missing required field: a');
  if (b === undefined) throw new Error('Missing required field: b');
  if (operation === undefined) throw new Error('Missing required field: operation');

  if (typeof a !== 'number' || Number.isNaN(a)) {
    throw new Error('Field "a" must be a number');
  }
  if (typeof b !== 'number' || Number.isNaN(b)) {
    throw new Error('Field "b" must be a number');
  }

  if (!(operation in OPERATIONS)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  if (operation === 'divide' && b === 0) {
    throw new Error('Division by zero is not allowed');
  }

  const result = OPERATIONS[operation](a, b);

  return {
    content: [{ type: 'text', text: String(result) }],
  };
}
